package com.zizou.EcommerceAPI.Entity;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

import org.hibernate.annotations.ColumnDefault;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.JoinTable;
import jakarta.persistence.ManyToMany;
import jakarta.persistence.ManyToOne;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;

@Entity
@Data
@AllArgsConstructor
@Builder
public class Livre {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY) // auto s'adapte en fonction de l abd hors pb historique
	private Long id;
	private String titre;
	private String resume;
	private double prix;
	private Date outDate;
	
	@ColumnDefault("0")
	@Column(nullable = false)
	private int quantiteStock = 0;

	@ColumnDefault("0")
	@Column(nullable = false)
	private int quantiteVendue = 0;

	
	@Column(length = 10000)
	private String openCouverture;
	
	@Column(length = 10000)
	private String closeCouverture;

	@ManyToOne
	@JoinColumn(name = "autheur_id")
	@JsonIgnoreProperties("livres")
	private Autheur autheur;
	
	
	// Merge veut dire ne recree plus dans la BD,mets a jour si changé puis fais un refresh
	@ManyToMany(cascade = {CascadeType.MERGE ,CascadeType.REFRESH})
	@JoinTable(name = "livre_cat", joinColumns = @JoinColumn(name = "livre_id"), inverseJoinColumns = @JoinColumn(name = "cat_id"))
	@JsonIgnoreProperties("livres")
	public List<Categorie> categories = new ArrayList<>();
	
	public Livre() {	
		this.openCouverture ="data:image/jpeg;base64,";
	}

	public Long getId() {
		return this.id;
	}

	public void setId(Long id) {
		this.id = id;
	}

	public String getTitre() {
		return titre;
	}

	public void setTitre(String titre) {
		this.titre = titre;
	}

	public String getResume() {
		return resume;
	}

	public void setResume(String resume) {
		this.resume = resume;
	}

	public double getPrix() {
		return prix;
	}

	public void setPrix(double prix) {
		this.prix = prix;
	}

	public Date getOutDate() {
		return outDate;
	}

	public void setOutDate(Date outDate) {
		this.outDate = outDate;
	}

	public int getQuantiteStock() {
		return quantiteStock;
	}

	public void setQuantiteStock(int quantiteStock) {
		this.quantiteStock = quantiteStock;
	}

	public int getQuantiteVendue() {
		return quantiteVendue;
	}

	public void setQuantiteVendue(int quantiteVendue) {
		this.quantiteVendue = quantiteVendue;
	}

	public String getOpenCouverture() {
		return openCouverture;
	}

	public void setOpenCouverture(String openCouverture) {
		this.openCouverture = openCouverture;
	}

	public String getCloseCouverture() {
		return closeCouverture;
	}

	public void setCloseCouverture(String closeCouverture) {
		this.closeCouverture = closeCouverture;
	}

	public Autheur getAutheur() {
		return autheur;
	}

	public void setAutheur(Autheur autheur) {
		this.autheur = autheur;
	}

	public List<Categorie> getCategories() {
		return categories;
	}

	public void setCategories(List<Categorie> categories) {
		this.categories = categories;
	}

}
